#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate event_ids (keep first), write deduped.jsonl."""

import json
import sys
from pathlib import Path


def main() -> None:
    seen: set[str] = set()
    out: list[str] = []

    src = Path("events.jsonl")
    if not src.is_file():
        print("error: events.jsonl not found in current directory", file=sys.stderr)
        sys.exit(1)

    with src.open(encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
            except json.JSONDecodeError as exc:
                print(f"warning: skipping malformed line: {exc}", file=sys.stderr)
                continue
            eid = obj.get("event_id")
            if eid is not None and eid not in seen:
                seen.add(eid)
                out.append(line)

    dest = Path("deduped.jsonl")
    with dest.open("w", encoding="utf-8") as f:
        for line in out:
            f.write(line + "\n")

    print(f"wrote {len(out)} events to {dest}")


if __name__ == "__main__":
    main()

