import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
MANIFEST_PATH = Path(__file__).resolve().parent / "manifest.json"


def sha256_digest(filepath: Path) -> str:
    return hashlib.sha256(filepath.read_bytes()).hexdigest()


def main() -> None:
    manifest = {}

    for path in sorted(RELEASE_DIR.rglob("*")):
        if not path.is_file():
            continue
        relative = path.relative_to(RELEASE_DIR)
        # Normalise to POSIX separators for cross-platform consistency
        manifest[str(relative.as_posix())] = sha256_digest(path)

    MANIFEST_PATH.write_text(json.dumps(manifest, indent=2) + "\n")


if __name__ == "__main__":
    main()

