#!/usr/bin/env python3
"""
rotate.py - Rotate old entries from app.log to archive.log.

Usage: python rotate.py AS_OF

Every line of app.log starts with a timestamp (YYYY-MM-DD HH:MM:SS).
Entries strictly older than 7 days before AS_OF are moved (appended) to
archive.log, preserving order.  app.log is rewritten with the remaining
entries in their original order.
"""

import sys
from datetime import datetime, timezone, timedelta


LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"
CUTOFF_DAYS = 7


def parse_ts(line: str):
    """Return a timezone-aware datetime from the leading 19 characters, or None."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=timezone.utc)
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print(f"Usage: python {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of_ts = int(sys.argv[1])
    except ValueError:
        print("Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = datetime.fromtimestamp(as_of_ts, tz=timezone.utc) - timedelta(days=CUTOFF_DAYS)

    try:
        with open(LOG_FILE) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"Error: {LOG_FILE} not found", file=sys.stderr)
        sys.exit(1)

    kept: list[str] = []
    moved: list[str] = []

    for line in lines:
        entry_dt = parse_ts(line)
        if entry_dt is not None and entry_dt < cutoff:
            moved.append(line)
        else:
            kept.append(line)

    if moved:
        with open(ARCHIVE_FILE, "a") as f:
            f.writelines(moved)

    with open(LOG_FILE, "w") as f:
        f.writelines(kept)


if __name__ == "__main__":
    main()

