#!/usr/bin/env python3
"""Rotate old entries from app.log to archive.log."""

import sys
from datetime import datetime, timezone

LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"
SEVEN_DAYS = 7 * 24 * 60 * 60  # seconds


def parse_ts(line: str) -> datetime | None:
    """Try to parse a leading 'YYYY-MM-DD HH:MM:SS' timestamp from *line*."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    as_of = int(sys.argv[1])
    cutoff_ts = as_of - SEVEN_DAYS  # strictly older than this -> archive

    try:
        with open(LOG_FILE) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"{LOG_FILE} not found, nothing to do.", file=sys.stderr)
        sys.exit(0)

    keep: list[str] = []
    archive: list[str] = []

    for line in lines:
        dt = parse_ts(line)
        if dt is not None and dt.timestamp() < cutoff_ts:
            archive.append(line)
        else:
            keep.append(line)

    # Append archived entries (in original order) to archive.log
    if archive:
        with open(ARCHIVE_FILE, "a") as f:
            f.writelines(archive)

    # Rewrite app.log with entries that were kept
    with open(LOG_FILE, "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

